  if(doc.schemaVersion===2&&doc.configVersion==='tribute-config-12'){const old=doc.state as Data;for(const ship of ((old.navy as Data|undefined)?.ships as Data[]|undefined)??[])ensure(!Object.hasOwn(ship,'role')&&!Object.hasOwn(ship,'passengers'),'legacy transport');for(const job of (((old.navy as Data|undefined)?.production as Data|undefined)?.queue as Data[]|undefined)??[])ensure(job.kind!=='transport','legacy transport job');doc.configVersion='tribute-config-13';}
